import {poseAt,skinMatrices,identity} from './rig.js';
export class Viewer {
 constructor(canvas){
 this.canvas=canvas;this.gl=canvas.getContext('webgl',{antialias:true,alpha:true,preserveDrawingBuffer:true});const gl=this.gl;if(!gl)throw Error('WebGLを利用できません。Safariで開き直してください。');
 const shader=(type,source)=>{const s=gl.createShader(type);gl.shaderSource(s,source);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw Error(gl.getShaderInfoLog(s));return s;};
 this.program=gl.createProgram();gl.attachShader(this.program,shader(gl.VERTEX_SHADER,`attribute vec3 position,normal,color,blink,smile,mouth;attribute vec4 joints,weights;uniform mat4 bones[17];uniform vec3 expression;uniform float yaw,pitch,zoom,aspect,target;varying vec3 N,C;void main(){mat4 skin=bones[int(joints.x)]*weights.x+bones[int(joints.y)]*weights.y+bones[int(joints.z)]*weights.z+bones[int(joints.w)]*weights.w;vec3 v=position+blink*expression.x+smile*expression.y+mouth*expression.z;mat3 ry=mat3(cos(yaw),0.,-sin(yaw),0.,1.,0.,sin(yaw),0.,cos(yaw));mat3 rx=mat3(1.,0.,0.,0.,cos(pitch),sin(pitch),0.,-sin(pitch),cos(pitch));vec3 p=rx*ry*((skin*vec4(v,1.)).xyz-vec3(0.,target,0.));N=rx*ry*(skin*vec4(normal,0.)).xyz;C=color;gl_Position=vec4(p.x*zoom/aspect,p.y*zoom,p.z*-.25,1.);}`));
 gl.attachShader(this.program,shader(gl.FRAGMENT_SHADER,`precision mediump float;varying vec3 N,C;uniform float roughness;void main(){vec3 n=normalize(N);if(!gl_FrontFacing)n=-n;float key=max(0.,dot(n,normalize(vec3(-.5,.8,1.))));float fill=max(0.,dot(n,normalize(vec3(.7,.2,.5))));float rim=pow(1.-abs(n.z),3.);float spec=pow(max(0.,dot(n,normalize(vec3(-.2,.5,1.)))),mix(70.,12.,roughness));vec3 c=C*(.33+key*.65+fill*.18)+vec3(.10,.13,.17)*rim+spec*(1.-roughness)*.28;gl_FragColor=vec4(c,1.);}`));gl.linkProgram(this.program);if(!gl.getProgramParameter(this.program,gl.LINK_STATUS))throw Error(gl.getProgramInfoLog(this.program));gl.useProgram(this.program);gl.enable(gl.DEPTH_TEST);this.uniforms={};for(const k of ['yaw','pitch','zoom','aspect','target','expression','bones','roughness'])this.uniforms[k]=gl.getUniformLocation(this.program,k==='bones'?'bones[0]':k);
 this.attributes={};for(const k of ['position','normal','color','joints','weights','blink','smile','mouth'])this.attributes[k]=gl.getAttribLocation(this.program,k);this.drawParts=[];
 }
 setMesh(mesh,wire=false){const gl=this.gl;for(const p of this.drawParts)for(const b of Object.values(p.buffers))gl.deleteBuffer(b);this.mesh=mesh;this.drawParts=[];this.wire=wire;
 const parts=mesh.parts||[{name:'Surface',group:'body',vertices:mesh.vertices,normals:mesh.normals,colors:mesh.colors,roughness:.6}];
 for(const p of parts){const indices=p.indices||Array.from({length:p.vertices.length/3},(_,i)=>i),order=[];for(let t=0;t<indices.length;t+=3){const [a,b,c]=[indices[t],indices[t+1],indices[t+2]];order.push(...(wire?[a,b,b,c,c,a]:[a,b,c]));}const buffers={};
 for(const [name,key,size]of [['position','vertices',3],['normal','normals',3],['color','colors',3],['joints','joints',4],['weights','weights',4],['blink','blink',3],['smile','smile',3],['mouth','mouth',3]]){const values=new Float32Array(order.length*size),src=p[key];for(let i=0;i<order.length;i++)for(let k=0;k<size;k++)values[i*size+k]=src?src[order[i]*size+k]:(name==='weights'&&k===0?1:0);buffers[name]=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,buffers[name]);gl.bufferData(gl.ARRAY_BUFFER,values,gl.STATIC_DRAW);}
 this.drawParts.push({group:p.group,buffers,count:order.length,roughness:p.roughness});}
 }
 render(state){const gl=this.gl,c=this.canvas,dpr=Math.min(devicePixelRatio||1,2),w=Math.max(1,Math.round(c.clientWidth*dpr)),h=Math.max(1,Math.round(c.clientHeight*dpr));if(c.width!==w||c.height!==h){c.width=w;c.height=h;}gl.useProgram(this.program);gl.disable(gl.SCISSOR_TEST);gl.clearColor(0,0,0,0);gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);if(!this.mesh)return;
 const sample=poseAt(state.pose,state.clip,state.time,state.expression),bones=this.mesh.rig?skinMatrices(this.mesh.rig,sample.rotations):new Float32Array(Array.from({length:17},identity).flat());gl.uniformMatrix4fv(this.uniforms.bones,false,bones);gl.uniform3fv(this.uniforms.expression,sample.expression);gl.uniform1f(this.uniforms.target,state.mode==='face'?this.mesh.headY:this.mesh.height*.51);
 const views=state.multi?[{x:0,y:h/2,w:w/2,h:h/2,yaw:0},{x:w/2,y:h/2,w:w/2,h:h/2,yaw:Math.PI/2},{x:0,y:0,w:w/2,h:h/2,yaw:Math.PI},{x:w/2,y:0,w:w/2,h:h/2,yaw:-Math.PI/2}]:[{x:0,y:0,w,h,yaw:state.yaw}];
 for(const v of views){gl.viewport(v.x,v.y,v.w,v.h);gl.uniform1f(this.uniforms.yaw,v.yaw);gl.uniform1f(this.uniforms.pitch,state.multi?0:state.pitch);gl.uniform1f(this.uniforms.zoom,state.zoom*(state.multi?.93:1));gl.uniform1f(this.uniforms.aspect,v.w/v.h);for(const p of this.drawParts){if(state.visibility?.[p.group]===false)continue;for(const [name,b] of Object.entries(p.buffers)){const a=this.attributes[name];if(a<0)continue;gl.bindBuffer(gl.ARRAY_BUFFER,b);gl.enableVertexAttribArray(a);gl.vertexAttribPointer(a,['joints','weights'].includes(name)?4:3,gl.FLOAT,false,0,0);}gl.uniform1f(this.uniforms.roughness,p.roughness);gl.drawArrays(this.wire?gl.LINES:gl.TRIANGLES,0,p.count);}}
 }
}
